{"command":"create","file_text":"//! Minimal JSON value parser and serializer used by the Rust jscodeshift CLI.
//! Only the subset required by the control layer: parsing of parser-config
//! files and bridge messages, and serialization of the options object that is
//! handed to the transform host.

use std::collections::BTreeMap;
use std::fmt::Write as _;

#[derive(Clone, Debug)]
pub enum Json {
    Null,
    Bool(bool),
    Number(f64),
    Str(String),
    Array(Vec<Json>),
    Object(Vec<(String, Json)>),
}

impl Json {
    pub fn as_str(&self) -> Option<&str> {
        if let Json::Str(s) = self { Some(s) } else { None }
    }
    pub fn as_bool(&self) -> Option<bool> {
        if let Json::Bool(b) = self { Some(*b) } else { None }
    }
    pub fn as_f64(&self) -> Option<f64> {
        if let Json::Number(n) = self { Some(*n) } else { None }
    }
}

pub fn parse(input: &str) -> Result<Json, String> {
    let bytes = input.as_bytes();
    let mut p = Parser { bytes, idx: 0 };
    p.skip_ws();
    let v = p.value()?;
    p.skip_ws();
    Ok(v)
}

struct Parser<'a> {
    bytes: &'a [u8],
    idx: usize,
}

impl<'a> Parser<'a> {
    fn skip_ws(&mut self) {
        while self.idx < self.bytes.len() {
            match self.bytes[self.idx] {
                b' ' | b'\t' | b'\n' | b'\r' => self.idx += 1,
                _ => break,
            }
        }
    }

    fn value(&mut self) -> Result<Json, String> {
        self.skip_ws();
        if self.idx >= self.bytes.len() {
            return Err("unexpected end of input".into());
        }
        match self.bytes[self.idx] {
            b'{' => self.object(),
            b'[' => self.array(),
            b'"' => self.string().map(Json::Str),
            b't' | b'f' => self.boolean(),
            b'n' => self.null(),
            b'-' | b'0'..=b'9' => self.number(),
            _ => Err(format!("unexpected char at {}", self.idx)),
        }
    }

    fn object(&mut self) -> Result<Json, String> {
        self.idx += 1; // {
        let mut entries = Vec::new();
        self.skip_ws();
        if self.idx < self.bytes.len() && self.bytes[self.idx] == b'}' {
            self.idx += 1;
            return Ok(Json::Object(entries));
        }
        loop {
            self.skip_ws();
            let key = self.string()?;
            self.skip_ws();
            if self.idx >= self.bytes.len() || self.bytes[self.idx] != b':' {
                return Err("expected :".into());
            }
            self.idx += 1;
            let val = self.value()?;
            entries.push((key, val));
            self.skip_ws();
            if self.idx >= self.bytes.len() {
                return Err("unterminated object".into());
            }
            match self.bytes[self.idx] {
                b',' => { self.idx += 1; }
                b'}' => { self.idx += 1; break; }
                _ => return Err("expected , or }".into()),
            }
        }
        Ok(Json::Object(entries))
    }

    fn array(&mut self) -> Result<Json, String> {
        self.idx += 1; // [
        let mut items = Vec::new();
        self.skip_ws();
        if self.idx < self.bytes.len() && self.bytes[self.idx] == b']' {
            self.idx += 1;
            return Ok(Json::Array(items));
        }
        loop {
            let v = self.value()?;
            items.push(v);
            self.skip_ws();
            if self.idx >= self.bytes.len() {
                return Err("unterminated array".into());
            }
            match self.bytes[self.idx] {
                b',' => { self.idx += 1; }
                b']' => { self.idx += 1; break; }
                _ => return Err("expected , or ]".into()),
            }
        }
        Ok(Json::Array(items))
    }

    fn string(&mut self) -> Result<String, String> {
        if self.idx >= self.bytes.len() || self.bytes[self.idx] != b'"' {
            return Err("expected string".into());
        }
        self.idx += 1;
        let mut out = String::new();
        while self.idx < self.bytes.len() {
            let c = self.bytes[self.idx];
            self.idx += 1;
            match c {
                b'"' => return Ok(out),
                b'\\' => {
                    if self.idx >= self.bytes.len() {
                        return Err("bad escape".into());
                    }
                    let e = self.bytes[self.idx];
                    self.idx += 1;
                    match e {
                        b'"' => out.push('"'),
                        b'\\' => out.push('\\'),
                        b'/' => out.push('/'),
                        b'b' => out.push('\u{0008}'),
                        b'f' => out.push('\u{000C}'),
                        b'n' => out.push('\n'),
                        b'r' => out.push('\r'),
                        b't' => out.push('\t'),
                        b'u' => {
                            let h = std::str::from_utf8(
                                &self.bytes[self.idx..self.idx + 4],
                            )
                            .map_err(|_| "bad unicode".to_string())?;
                            let cp = u32::from_str_radix(h, 16)
                                .map_err(|_| "bad unicode".to_string())?;
                            self.idx += 4;
                            if (0xD800..=0xDBFF).contains(&cp) {
                                // surrogate pair
                                if self.bytes.get(self.idx..self.idx + 6)
                                    == Some(b"\\u")
                                {
                                    let h2 = std::str::from_utf8(
                                        &self.bytes[self.idx + 2..self.idx + 6],
                                    )
                                    .map_err(|_| "bad unicode".to_string())?;
                                    let cp2 = u32::from_str_radix(h2, 16)
                                        .map_err(|_| "bad unicode".to_string())?;
                                    self.idx += 6;
                                    let c = 0x10000
                                        + ((cp - 0xD800) << 10)
                                        + (cp2 - 0xDC00);
                                    out.push(char::from_u32(c).unwrap_or('\u{FFFD}'));
                                } else {
                                    out.push('\u{FFFD}');
                                }
                            } else {
                                out.push(char::from_u32(cp).unwrap_or('\u{FFFD}'));
                            }
                        }
                        _ => return Err("bad escape".into()),
                    }
                }
                _ => out.push(c as char),
            }
        }
        Err("unterminated string".into())
    }

    fn boolean(&mut self) -> Result<Json, String> {
        if self.bytes[self.idx..].starts_with(b"true") {
            self.idx += 4;
            Ok(Json::Bool(true))
        } else if self.bytes[self.idx..].starts_with(b"false") {
            self.idx += 5;
            Ok(Json::Bool(false))
        } else {
            Err("bad bool".into())
        }
    }

    fn null(&mut self) -> Result<Json, String> {
        if self.bytes[self.idx..].starts_with(b"null") {
            self.idx += 4;
            Ok(Json::Null)
        } else {
            Err("bad null".into())
        }
    }

    fn number(&mut self) -> Result<Json, String> {
        let start = self.idx;
        if self.bytes[self.idx] == b'-' {
            self.idx += 1;
        }
        while self.idx < self.bytes.len() {
            match self.bytes[self.idx] {
                b'0'..=b'9' | b'.' | b'e' | b'E' | b'+' | b'-' => self.idx += 1,
                _ => break,
            }
        }
        let s = std::str::from_utf8(&self.bytes[start..self.idx])
            .map_err(|_| "bad number".to_string())?;
        s.parse::<f64>().map(Json::Number).map_err(|_| "bad number".into())
    }
}

pub fn write_string(out: &mut String, s: &str) {
    out.push('"');
    for c in s.chars() {
        match c {
            '"' => out.push_str("\\\""),
            '\\' => out.push_str("\\\\"),
            '\n' => out.push_str("\\n"),
            '\r' => out.push_str("\\r"),
            '\t' => out.push_str("\\t"),
            '\u{0008}' => out.push_str("\\b"),
            '\u{000C}' => out.push_str("\\f"),
            c if (c as u32) < 0x20 => {
                let _ = write!(out, "\\u{:04x}", c as u32);
            }
            c => out.push(c),
        }
    }
    out.push('"');
}

pub fn serialize(value: &Json, out: &mut String) {
    match value {
        Json::Null => out.push_str("null"),
        Json::Bool(b) => out.push_str(if *b { "true" } else { "false" }),
        Json::Number(n) => {
            // Match JS JSON.stringify number formatting closely enough.
            if n.is_nan() || n.is_infinite() {
                out.push_str("null");
            } else if n.fract() == 0.0 && n.abs() < 1e21 {
                let _ = write!(out, "{}", *n as i64);
            } else {
                let _ = write!(out, "{}", n);
            }
        }
        Json::Str(s) => write_string(out, s),
        Json::Array(a) => {
            out.push('[');
            for (i, v) in a.iter().enumerate() {
                if i > 0 { out.push(','); }
                serialize(v, out);
            }
            out.push(']');
        }
        Json::Object(o) => {
            out.push('{');
            for (i, (k, v)) in o.iter().enumerate() {
                if i > 0 { out.push(','); }
                write_string(out, k);
                out.push(':');
                serialize(v, out);
            }
            out.push('}');
        }
    }
}

/// Coerce a Rust-side option value into a Json value for serialization.
pub fn from_bool(b: bool) -> Json { Json::Bool(b) }
pub fn from_str(s: &str) -> Json { Json::Str(s.to_string()) }
pub fn from_num(n: f64) -> Json { Json::Number(n) }

/// Helper type for building the options object handed to the bridge.
pub struct ObjBuilder {
    pub entries: Vec<(String, Json)>,
}

impl ObjBuilder {
    pub fn new() -> Self { ObjBuilder { entries: Vec::new() } }
    pub fn push(&mut self, key: &str, val: Json) {
        self.entries.push((key.to_string(), val));
    }
    pub fn build(self) -> Json { Json::Object(self.entries) }
}

pub fn get(o: &Json, key: &str) -> Option<&Json> {
    if let Json::Object(entries) = o {
        entries.iter().find(|(k, _)| k == key).map(|(_, v)| v)
    } else {
