pub fn build_help_text(specs: &[OptSpec]) -> String {
    // help is inserted with display_index 5 (no default), no abbr beyond 'h'
    let help_opt = OptSpec {
        key: "help".into(), full: "help".into(), abbr: Some("h".into()), flag: false, list: false,
        default: None, default_help: None, choices: None, choices_num: None,
        metavar: None, help: Some("print this help and exit".into()),
        process_num: false, process_json_file: false, display_index: 5, callback_help: true, callback_version: false,
    };
    let mut all: Vec<&OptSpec> = specs.iter().collect();
    all.push(&help_opt);
    all.sort_by_key(|s| s.display_index);

    let header = "\nUsage: jscodeshift [OPTION]... PATH...\n  or:  jscodeshift [OPTION]... -t TRANSFORM_PATH PATH...\n  or:  jscodeshift [OPTION]... -t URL PATH...\n  or:  jscodeshift [OPTION]... --stdin < file_list.txt\n\nApply transform logic in TRANSFORM_PATH (recursively) to every PATH.\nIf --stdin is set, each line of the standard input is used as a path.\n\nOptions:\n\"...\" behind an option means that it can be supplied multiple times.\nAll options are also passed to the transformer, which means you can supply custom options that are not listed here.\n\n";
    let body: Vec<String> = all.iter().map(|o| format_option(o)).collect();
    let mut text = String::from(header);
    text.push_str(&body.join("\n"));
    text.push('\n');
    // trimLeft in JS trims leading whitespace; here header already starts with \n.
    // getHelpText returns header + join + "\n", then trimLeft removes leading ws (\n and spaces).
    text.trim_start().to_string()
}

fn format_option(o: &OptSpec) -> String {
    let mut text = String::from("  ");
    if let Some(abbr) = &o.abbr {
        text.push_str(&format!("-{}, ", abbr));
    } else {
        text.push_str("    ");
    }
    text.push_str("--");
    if o.flag { text.push_str("(no-)"); }
    text.push_str(&o.full);
    if let Some(choices) = &o.choices {
        text.push_str(&format!("={}", choices.join("|")));
    } else if let Some(mv) = &o.metavar {
        text.push_str(&format!("={}", mv));
    }
    if o.list { text.push_str(" ..."); }
    if o.default_help.is_some() || o.default.is_some() || o.help.is_some() {
        text.push_str("  ");
        if text.chars().count() < 32 {
            let pad = 32 - text.chars().count();
            for _ in 0..pad { text.push(' '); }
        }
        let text_length = text.chars().count();
        if let Some(help) = &o.help {
            text.push_str(help);
        }
        if o.default_help.is_some() || o.default.is_some() {
            if o.help.is_some() {
                text.push('\n');
            }
            for _ in 0..text_length { text.push(' '); }
            text.push_str("(default: ");
            if let Some(dh) = &o.default_help {
                text.push_str(dh);
            } else if let Some(d) = &o.default {
                text.push_str(&default_display(d));
            }
            text.push(')');
        }
    }
    text
}

fn default_display(v: &Json) -> String {
    match v {
        Json::Bool(b) => b.to_string(),
        Json::Number(n) => {
            if n.fract() == 0.0 { format!("{}", *n as i64) } else { format!("{}", n) }
        }
        Json::Str(s) => s.clone(),
        _ => "[]".to_string(),
    }
}

pub enum ParseOutcome {
    Run(ParseResult),
    Exit { code: i32, message: String, to_stderr: bool },
}

/// Parse argv (excluding the program name). Returns either a result to act on
/// or an early exit (help/version/error).
pub fn parse_argv(argv: &[String], specs: &[OptSpec], help_text: &str) -> ParseOutcome {
    // prepareOptions: build lookup, set up defaults
    let mut prepared: HashMap<String, usize> = HashMap::new();
    for (i, o) in specs.iter().enumerate() {
        prepared.insert(format!("--{}", o.full), i);
        if let Some(abbr) = &o.abbr {
            prepared.insert(format!("-{}", abbr), i);
        }
        if o.flag {
            prepared.insert(format!("--no-{}", o.full), i);
        }
    }

    let mut options: HashMap<String, Json> = HashMap::new();
    let mut positional: Vec<Json> = Vec::new();

    for o in specs.iter() {
        if let Some(d) = &o.default {
            options.insert(o.key.clone(), d.clone());
        } else if o.list {
            options.insert(o.key.clone(), Json::Array(Vec::new()));
        }
    }

