    // Note: nomnom treats anything starting with - or -- as option. But a bare "-"
    // is a positional. Replicate isOption = /^--?/.test(value) => starts with - or --.
    let is_option_js = |v: &str| v.starts_with('-');

    let mut i = 0;
    let mut missing: Vec<String> = Vec::new();
    while i < argv.len() {
        let arg = argv[i].clone();
        if is_option_js(&arg) {
            let mut option_name = arg.clone();
            let mut value: Option<String> = None;
            if let Some(idx) = arg.find('=') {
                option_name = arg[..idx].to_string();
                value = Some(arg[idx + 1..].to_string());
            }
            let known = prepared.get(&option_name).copied();
            let (full, key, flag, list, process_num, process_json_file) = match known {
                Some(idx) => {
                    let o = &specs[idx];
                    (o.full.clone(), o.key.clone(), o.flag, o.list, o.process_num, o.process_json_file)
                }
                None => {
                    // unknown option
                    let re_no = regex_no_prefix(&option_name);
                    let real_name: String = re_no.unwrap_or_else(|| option_name.trim_start_matches('-').to_string());
                    let cur = options.get(&real_name);
                    let is_list = cur.is_some() && !matches!(cur, Some(Json::Bool(true)));
                    let next_is_opt = i + 1 < argv.len() && is_option_js(&argv[i + 1]);
                    let flag_unknown = cur.is_none() && value.is_none() && next_is_opt;
                    if is_list {
                        if let Some(Json::Array(_)) = cur {
                            // already a list
                        } else {
                            // convert to list; if current is true, discard to []
                            let newv = match cur {
                                Some(Json::Bool(true)) => Json::Array(Vec::new()),
                                Some(other) => Json::Array(vec![other.clone()]),
                                None => Json::Array(Vec::new()),
                            };
                            options.insert(real_name.clone(), newv);
                        }
                    }
                    (real_name.clone(), real_name, flag_unknown, is_list, false, false)
                }
            };

            // callbacks (help/version) only exist for known options; unknown never has callback.
            if known.is_none() {
                // fall through to flag/value handling below with the synthesized option
                if flag {
                    let val = if option_name.starts_with("--no-") {
                        false
                    } else if let Some(v) = &value {
                        v == "1"
                    } else {
                        true
                    };
                    options.insert(key, Json::Bool(val));
                } else {
                    // value handling
                    let mut val = value;
                    if val.is_none() && i + 1 < argv.len() && !is_option_js(&argv[i + 1]) {
                        val = Some(argv[i + 1].clone());
                        i += 1;
                    }
                    if let Some(v) = val {
                        let processed = process_value(&v, false, false);
                        if list {
                            if let Some(Json::Array(a)) = options.get_mut(&key) {
                                a.push(processed);
                            } else {
                                options.insert(key.clone(), Json::Array(vec![processed]));
                            }
                        } else {
                            options.insert(key, processed);
                        }
                    } else {
                        missing.push(key);
                    }
                }
                i += 1;
                continue;
            }

            // known option
            let o = &specs[known.unwrap()];
            if o.callback_help {
                return ParseOutcome::Exit { code: 0, message: help_text.to_string(), to_stderr: false };
            }
            if o.callback_version {
                // handled by caller; signal via special key. We'll detect version before calling.
                // Should not reach here because version callback returns help text in JS; but in bin
                // the callback returns the version string. We handle version externally.
                return ParseOutcome::Exit { code: 0, message: String::new(), to_stderr: false };
            }
            if o.flag {
                let val = if option_name.starts_with("--no-") {
                    false
                } else if let Some(v) = &value {
                    v == "1"
                } else {
                    true
                };
                options.insert(o.key.clone(), Json::Bool(val));
            } else {
                let mut val = value;
                if val.is_none() && i + 1 < argv.len() && !is_option_js(&argv[i + 1]) {
                    val = Some(argv[i + 1].clone());
                    i += 1;
                }
                if let Some(v) = val {
                    let processed = process_value(&v, process_num, process_json_file);
                    if o.list {
                        if let Some(Json::Array(a)) = options.get_mut(&o.key) {
                            a.push(processed);
                        }
                    } else {
                        options.insert(o.key.clone(), processed);
                    }
                } else {
                    missing.push(o.key.clone());
                }
            }
            let _ = (full, flag, list, process_num, process_json_file);
        } else {
            // positional
            if arg.chars().all(|c| c.is_ascii_digit()) && !arg.is_empty() {
                positional.push(Json::Number(arg.parse::<f64>().unwrap_or(0.0)));
            } else {
                positional.push(Json::Str(arg));
            }
        }
        i += 1;
    }

    // missing values
    if !missing.is_empty() {
        // JS: `Missing value: --${options[optionName].full} requires a value`
        // options here refers to the ORIGINAL spec object keyed by property name; for unknown
        // options, options[optionName] is undefined -> full is undefined. We replicate by looking
        // up the spec by key; if not found, full is "undefined".
        let msg = missing.iter().map(|k| {
            let full = specs.iter().find(|s| &s.key == k).map(|s| s.full.clone()).unwrap_or_else(|| "undefined".to_string());
            format!("Missing value: --{} requires a value", full)
        }).collect::<Vec<_>>().join("\n");
        let message = format!("{}\n\n---\n\n{}", msg, help_text);
        return ParseOutcome::Exit { code: 1, message, to_stderr: true };
    }

    // validate choices
    let mut errors: Vec<String> = Vec::new();
    for o in specs.iter() {
        if let Some(choices) = &o.choices {
            let val = options.get(&o.key);
            let ok = match val {
                Some(Json::Str(s)) => choices.iter().any(|c| c == s),
                _ => false,
            };
            if !ok {
                errors.push(format!("Error: --{} must be one of the values {}", o.full, choices.join(",")));
            }
        }
        if let Some(choices_num) = &o.choices_num {
            let val = options.get(&o.key);
            let ok = match val {
                Some(Json::Number(n)) => choices_num.iter().any(|c| (*c as f64) == *n),
                _ => false,
            };
            if !ok {
                errors.push(format!("Error: --{} must be one of the values {}", o.full, choices_num.iter().map(|c| c.to_string()).collect::<Vec<_>>().join(",")));
            }
        }
    }
    if !errors.is_empty() {
        let message = format!("{}\n\n---\n\n{}", errors.join("\n"), help_text);
        return ParseOutcome::Exit { code: 1, message, to_stderr: true };
    }

    ParseOutcome::Run(ParseResult { options, positional, help_text: help_text.to_string() })
}

fn regex_no_prefix(name: &str) -> Option<String> {
    // matches /^--?(no-)?/  -> capture the part after optional leading -/-- and optional no-
    let s = name.trim_start_matches('-');
    if let Some(rest) = s.strip_prefix("no-") {
        Some(rest.to_string())
    } else if s == name.trim_start_matches('-') && !s.is_empty() {
        Some(s.to_string())
    } else {
        None
    }
}

fn process_value(v: &str, as_num: bool, as_json_file: bool) -> Json {
    if as_num {
        if let Ok(n) = v.parse::<f64>() {
            return Json::Number(n);
        }
        return Json::Str(v.to_string());
    }
    if as_json_file {
        if let Ok(content) = std::fs::read_to_string(v) {
            if let Ok(parsed) = crate::json::parse(&content) {
                return parsed;
            }
        }
        // JS throws if file can't be read; but parse runs during arg parsing and the
        // error propagates. For our purposes, fall back to the raw string.
        return Json::Str(v.to_string());
    }
    // Try JSON.parse; fallback to string
    if v == "true" { return Json::Bool(true); }
    if v == "false" { return Json::Bool(false); }
    if v == "null" { return Json::Null; }
    if let Ok(n) = v.parse::<f64>() {
        // JSON.parse('5') => 5; JSON.parse('5.5') => 5.5; JSON.parse('01') throws
        // Only treat as number if it's a valid JSON number (no leading zeros except 0 itself).
        if looks_like_json_number(v) {
            return Json::Number(n);
        }
    }
    // Try parsing as JSON object/array/string
    if v.starts_with('{') || v.starts_with('[') || v.starts_with('"') {
        if let Ok(parsed) = crate::json::parse(v) {
            return parsed;
        }
    }
    Json::Str(v.to_string())
}

fn looks_like_json_number(v: &str) -> bool {
    let b = v.as_bytes();
    if b.is_empty() { return false; }
    let mut idx = 0;
    if b[0] == b'-' { idx += 1; }
    if idx >= b.len() { return false; }
    if b[idx] == b'0' {
        idx += 1;
    } else if b[idx].is_ascii_digit() {
        while idx < b.len() && b[idx].is_ascii_digit() { idx += 1; }
    } else {
        return false;
    }
    if idx < b.len() && b[idx] == b'.' {
        idx += 1;
        let start = idx;
        while idx < b.len() && b[idx].is_ascii_digit() { idx += 1; }
        if idx == start { return false; }
    }
    if idx < b.len() && (b[idx] == b'e' || b[idx] == b'E') {
        idx += 1;
        if idx < b.len() && (b[idx] == b'+' || b[idx] == b'-') { idx += 1; }
        let start = idx;
        while idx < b.len() && b[idx].is_ascii_digit() { idx += 1; }
        if idx == start { return false; }
    }
    idx == b.len()
