//! and matching mirror the original behavior: picomatch with `dot: true`.

use std::fs;
use std::path::Path;

pub struct Ignore {
    matchers: Vec<String>,
}

impl Ignore {
    pub fn new() -> Self { Ignore { matchers: Vec::new() } }

    pub fn add_from_input(&mut self, input: Option<&Vec<String>>) {
        if let Some(input) = input {
            for pat in input {
                self.add_ignore_pattern(pat);
            }
        }
    }

    pub fn add_from_file(&mut self, input: Option<&Vec<String>>) {
        if let Some(input) = input {
            for config in input {
                if let Ok(meta) = fs::metadata(config) {
                    if meta.is_file() {
                        if let Ok(content) = fs::read_to_string(config) {
                            for line in content.split('\n').flat_map(|l| {
                                // split(/\r?\n/) -> split on \r\n or \n
                                let l = l.trim_end_matches('\r');
                                if l.is_empty() { None } else { Some(l.to_string()) }
                            }) {
                                self.add_ignore_pattern(&line);
                            }
                            // Note: the original concatenates content.split(/\r?\n/), which
                            // yields an array; empty lines are added too. We replicate the
                            // "push every element" behavior precisely below instead.
                        }
                    }
                }
            }
        }
    }

    pub fn add_ignore_pattern(&mut self, val: &str) {
        if val.is_empty() || val.starts_with('#') {
            return;
        }
        let pattern = val;
        if !pattern.contains('/') {
            self.matchers.push(format!("**/{}", pattern));
        } else if pattern.ends_with('/') {
            self.matchers.push(format!("**/{}**", pattern));
            self.matchers.push(format!("{}**", pattern));
        }
        self.matchers.push(pattern.to_string());
    }

    pub fn should_ignore(&self, path: &str) -> bool {
        if self.matchers.is_empty() {
            return false;
        }
        let normalized = strip_leading_traversal(path);
        picomatch_is_match(path, &self.matchers)
            || (normalized != path && picomatch_is_match(&normalized, &self.matchers))
    }
}

fn strip_leading_traversal(p: &str) -> String {
    let mut s = p;
    loop {
        if let Some(rest) = s.strip_prefix("./") {
            s = rest;
        } else if let Some(rest) = s.strip_prefix("../") {
            s = rest;
        } else {
            break;
        }
    }
    s.to_string()
}

/// Picomatch-compatible glob matching with `dot: true`. Handles the subset of
/// patterns produced by ignoreFiles.addIgnorePattern: `**`, `*`, `?`, literal
/// segments, `/`-anchored patterns, and trailing `**`.
pub fn picomatch_is_match(input: &str, patterns: &[String]) -> bool {
    patterns.iter().any(|p| match_one(input, p))
}

fn match_one(input: &str, pattern: &str) -> bool {
    // Normalize backslashes to forward slashes for matching consistency.
    let input = input.replace('\\', "/");
    let pattern = pattern.replace('\\', "/");
    glob_match(&input, &pattern)
}

/// Glob match supporting `**`, `*`, `?`, and literal chars. With `dot: true`,
/// `*` and `?` also match leading-dot path segments.
fn glob_match(input: &str, pattern: &str) -> bool {
    let i: Vec<char> = input.chars().collect();
    let p: Vec<char> = pattern.chars().collect();
    glob_rec(&i, 0, &p, 0)
}

fn glob_rec(i: &[char], mut ii: usize, p: &[char], mut pi: usize) -> bool {
    while pi < p.len() {
        let c = p[pi];
        if c == '*' {
            if pi + 1 < p.len() && p[pi + 1] == '*' {
                // `**`
                // `**` matches any number of characters, including `/`.
                // Consume the `**` (and a following slash if present, since `**/`
                // matches zero dirs).
                pi += 2;
                if pi < p.len() && p[pi] == '/' {
                    pi += 1;
                    // `**/` can match zero dirs: try matching rest at current pos
                    // and also skipping directories.
                    // Try every suffix starting at ii.
                    let mut k = ii;
                    loop {
                        if glob_rec(i, k, p, pi) {
                            return true;
                        }
                        if k >= i.len() { break; }
                        // advance to next directory boundary or char
                        if i[k] == '/' {
                            k += 1;
                            // also allow matching across this slash
                        } else {
                            k += 1;
                        }
                    }
                    return false;
                } else {
                    // trailing `**` matches everything
                    return true;
                }
            } else {
                // `*` matches any chars except `/`
                pi += 1;
                // try to match the rest of the pattern against every prefix that
                // doesn't cross a `/`.
                let mut k = ii;
                loop {
                    if glob_rec(i, k, p, pi) {
                        return true;
                    }
                    if k >= i.len() || i[k] == '/' {
                        break;
                    }
                    k += 1;
                }
                return false;
            }
        } else if c == '?' {
            if ii >= i.len() || i[ii] == '/' {
                return false;
            }
            ii += 1;
            pi += 1;
        } else {
            if ii >= i.len() || i[ii] != c {
                return false;
            }
            ii += 1;
            pi += 1;
        }
    }
    ii == i.len()
}

/// Read gitignore-style file patterns. Returns the raw lines (split on \r?\n),
/// mirroring `content.split(/\r?\n/)` which keeps empty entries.
pub fn read_ignore_file_lines(path: &Path) -> Vec<String> {
    match fs::read_to_string(path) {
        Ok(content) => content.split("\r\n").flat_map(|seg| seg.split('\n')).map(|s| s.to_string()).collect(),
        Err(_) => Vec::new(),
    }
