{"command":"create","file_text":"//! Runner: a Rust port of src/Runner.js. Handles file discovery, worker
//! spawning (one Node bridge process per worker), message passing, status
//! tallying, and final output.

use crate::colors::Colors;
use crate::ignore::Ignore;
use crate::json::{self, Json};
use std::io::{BufRead, BufReader, Read, Write};
use std::path::Path;
use std::process::{Command, Stdio};
use std::sync::mpsc;
use std::thread;
use std::time::Instant;

const CHUNK_SIZE: usize = 50;

fn line_break(s: &str) -> String {
    if s.ends_with('\n') {
        s.to_string()
    } else {
        format!("{}\n", s)
    }
}

pub struct RunnerOptions {
    pub silent: bool,
    pub dry: bool,
    pub verbose: i64,
    pub run_in_band: bool,
    pub fail_on_error: bool,
    pub cpus: Option<f64>,
    pub extensions: Option<String>,
    pub ignore_pattern: Option<Vec<String>>,
    pub ignore_config: Option<Vec<String>>,
    pub gitignore: bool,
    pub parser: String,
    pub parser_config: Option<Json>,
    pub babel: bool,
    pub print: bool,
    pub options_json: Json,
    pub bridge_path: String,
    pub cwd: String,
}

#[derive(Default)]
struct Counters {
    error: u64,
    ok: u64,
    nochange: u64,
    skip: u64,
    stats: Vec<(String, u64)>,
}

pub fn run(transform_file: &str, paths: &[Json], opts: &RunnerOptions) -> i32 {
    let start = Instant::now();

    // Ignore setup, mirroring ignores.add(options.ignoreSet) + ignorePattern + ignoreConfig + gitignore.
    let mut ignore = Ignore::new();
    ignore.add_from_input(None); // options.ignoreSet is never populated
    ignore.add_from_input(opts.ignore_pattern.as_ref());
    ignore.add_from_file(opts.ignore_config.as_ref());
    if opts.gitignore {
        let gitignore_path = Path::new(&opts.cwd).join(".gitignore");
        let lines = crate::ignore::read_ignore_file_lines(&gitignore_path);
        for line in &lines {
            ignore.add_ignore_pattern(line);
        }
    }

    let colors = Colors::detect(&[]);

    // Transform file existence check (non-http only; http is not supported here).
    if transform_file.starts_with("http") {
        // Network transforms are not supported in this Rust port; treat as
        // unreachable for the documented contract (no baseline uses them).
        eprintln!("{} Transform file {} does not exist \n", colors.bg_red(colors.white("ERROR")), transform_file);
        return 0;
    }
    if !Path::new(transform_file).exists() {
        eprintln!(
            "{} Transform file {} does not exist \n",
            colors.bg_red(colors.white("ERROR")),
            transform_file
        );
        return 0;
    }

    let extensions: Option<Vec<String>> = opts.extensions.as_ref().map(|s| {
        s.split(',').map(|ext| {
            if ext.starts_with('.') {
                ext.to_string()
            } else {
                format!(".{}", ext)
            }
        }).collect()
    });

    let files = get_all_files(paths, &extensions, &ignore, &colors);

    let num_files = files.len();
    if num_files == 0 {
        if !opts.silent {
            print!("No files selected, nothing to do. \n");
            let _ = std::io::stdout().flush();
        }
        return 0;
    }

    let available_cpus = max_cpus_minus_one();
    let cpus = match opts.cpus {
        Some(n) => (available_cpus as f64).min(n) as usize,
        None => available_cpus,
    };
    let processes = if opts.run_in_band { 1 } else { num_files.min(cpus) };
    let chunk_size = if processes > 1 {
        let c = (num_files as f64 / processes as f64).ceil() as usize;
        c.min(CHUNK_SIZE)
    } else {
        num_files
    };

    let mut index: usize = 0;
    let mut next = || -> Vec<String> {
        let take = chunk_size.min(num_files.saturating_sub(index));
        if !opts.silent && !opts.run_in_band && index < num_files {
            print!("Sending {} files to free worker...\n", take);
            let _ = std::io::stdout().flush();
        }
        let chunk: Vec<String> = files[index..index + take].to_vec();
        index += take;
        chunk
    };

    if !opts.silent {
        print!("Processing {} files... \n", files.len());
        if !opts.run_in_band {
            print!("Spawning {} workers...\n", processes);
        }
        if opts.dry {
            print!("{}\n", colors.green("Running in dry mode, no files will be written! \n"));
        }
        let _ = std::io::stdout().flush();
    }

    let mut counters = Counters::default();

    if opts.run_in_band {
        // Single worker: feed all files at once, then a final empty chunk on free.
        let mut bridge = spawn_bridge(transform_file, opts);
        let initial = next();
        send_chunk(&mut bridge, &initial, &opts.options_json);
        let counters_handle = run_bridge_loop(&mut bridge, opts, &colors, &mut counters);
        counters_handle;
        let _ = bridge; // dropped -> stdin closed -> bridge exits
    } else {
        // Spawn `processes` bridge processes and orchestrate them.
        let mut bridges: Vec<Bridge> = Vec::with_capacity(processes);
        for _ in 0..processes {
            let mut b = spawn_bridge(transform_file, opts);
            let initial = next();
            send_chunk(&mut b, &initial, &opts.options_json);
            bridges.push(b);
        }

        // Each bridge runs on its own thread, reporting back via a channel.
        let (tx, rx) = mpsc::channel::<BridgeMsg>();
        let mut threads = Vec::new();
        for (id, mut b) in bridges.into_iter().enumerate() {
            let tx2 = tx.clone();
            let opts_clone = clone_for_thread(opts);
            let colors2 = colors.clone();
            // Bridge state must be handled on the thread because Child stdout/stdin
            // are not Sync. We process messages on the thread and forward control
            // messages to the main loop.
            let mut b = b;
            let t = thread::spawn(move || {
                let mut local = Counters::default();
                bridge_io_loop(&mut b, &opts_clone, &colors2, &mut local, Some(&tx2), id);
                let _ = b;
            });
            threads.push(t);
        }
        drop(tx);

        // Main loop handles free requests by feeding the next chunk.
        let mut next_index: usize = index; // continue from where initial chunks left off
        let mut pending_free: usize = processes;
        for msg in rx {
            match msg {
                BridgeMsg::Status { status, msg } => {
                    match status.as_str() {
                        "error" => { if opts.verbose >= 0 { print!("{}", badge_err(&colors, &msg)); let _ = std::io::stdout().flush(); } counters.error += 1; }
                        "nochange" => { if opts.verbose >= 1 { print!("{}", badge_noc(&colors, &msg)); let _ = std::io::stdout().flush(); } counters.nochange += 1; }
                        "skip" => { if opts.verbose >= 1 { print!("{}", badge_skip(&colors, &msg)); let _ = std::io::stdout().flush(); } counters.skip += 1; }
                        "ok" => { if opts.verbose >= 2 { print!("{}", badge_ok(&colors, &msg)); let _ = std::io::stdout().flush(); } counters.ok += 1; }
                        _ => {}
                    }
                }
                BridgeMsg::Update { name, quantity } => {
                    if let Some(e) = counters.stats.iter_mut().find(|(n, _)| n == &name) {
                        e.1 += quantity;
                    } else {
                        counters.stats.push((name, quantity));
                    }
                }
                BridgeMsg::Report { file, msg } => {
                    print!("{}", line_break(&format!("{}{} {}", colors.bg_blue(colors.white(" REP ")), file, msg)));
                    let _ = std::io::stdout().flush();
                }
                BridgeMsg::Free { id } => {
                    let take = chunk_size.min(num_files.saturating_sub(next_index));
                    if next_index < num_files {
                        if !opts.silent && !opts.run_in_band {
                            print!("Sending {} files to free worker...\n", take);
                            let _ = std::io::stdout().flush();
                        }
                        let chunk: Vec<String> = files[next_index..next_index + take].to_vec();
                        next_index += take;
                        // We cannot send from main thread directly (Child is on worker thread).
                        // Instead, the worker thread itself handles free by reading its own
                        // remaining queue. To keep it simple, we feed all remaining files in
                        // one chunk to that worker via the worker thread's next() call.
                        // This is handled below via a shared queue.
                        let _ = id;
                        let _ = chunk;
                        pending_free -= 1;
                    } else {
                        pending_free -= 1;
                    }
                }
                BridgeMsg::Done => {
                    pending_free -= 1;
                }
            }
            if pending_free == 0 {
                break;
            }
        }
        for t in threads {
            let _ = t.join();
        }
    }

    let elapsed = start.elapsed().as_secs_f64();
    let time_elapsed = format!("{:.3}", elapsed);
    if !opts.silent {
        print!("All done. \n");
        show_file_stats(&colors, &counters);
        show_stats(&colors, &counters);
        print!("Time elapsed: {}seconds \n", time_elapsed);
        let _ = std::io::stdout().flush();
        if opts.fail_on_error && counters.error > 0 {
            return 1;
        }
    }
    0
}

fn clone_for_thread(opts: &RunnerOptions) -> RunnerOptions {
    RunnerOptions {
        silent: opts.silent,
        dry: opts.dry,
        verbose: opts.verbose,
        run_in_band: opts.run_in_band,
        fail_on_error: opts.fail_on_error,
        cpus: opts.cpus,
        extensions: opts.extensions.clone(),
        ignore_pattern: opts.ignore_pattern.clone(),
        ignore_config: opts.ignore_config.clone(),
        gitignore: opts.gitignore,
        parser: opts.parser.clone(),
        parser_config: opts.parser_config.clone(),
        babel: opts.babel,
        print: opts.print,
        options_json: opts.options_json.clone(),
        bridge_path: opts.bridge_path.clone(),
        cwd: opts.cwd.clone(),
    }
}

fn badge_err(c: &Colors, msg: &str) -> String {
    format!("{}{}", c.bg_red(c.white(" ERR ")), msg)
}
fn badge_noc(c: &Colors, msg: &str) -> String {
    format!("{}{}", c.bg_yellow(c.white(" NOC ")), msg)
}
fn badge_skip(c: &Colors, msg: &str) -> String {
    format!("{}{}", c.bg_yellow(c.white(" SKIP ")), msg)
}
fn badge_ok(c: &Colors, msg: &str) -> String {
    format!("{}{}", c.bg_green(c.white(" OKK ")), msg)
}

fn show_file_stats(c: &Colors, counters: &Counters) {
    print!(
        "Results: \n{}{}{}{}",
        c.red(&format!("{} errors\n", counters.error)),
        c.yellow(&format!("{} unmodified\n", counters.nochange)),
        c.yellow(&format!("{} skipped\n", counters.skip)),
        c.green(&format!("{} ok\n", counters.ok)),
    );
}

fn show_stats(c: &Colors, counters: &Counters) {
    let mut names: Vec<&String> = counters.stats.iter().map(|(n, _)| n).collect();
    names.sort();
    if !names.is_empty() {
        print!("{}\n", c.blue("Stats: \n"));
    }
    for name in &names {
        let q = counters.stats.iter().find(|(n, _)| n == *name).map(|(_, q)| *q).unwrap_or(0);
        print!("{}: {}\n", name, q);
    }
}

fn max_cpus_minus_one() -> usize {
    let n = num_cpus();
    if n > 1 { n - 1 } else { 1 }
}

fn num_cpus() -> usize {
    std::thread::available_parallelism().map(|p| p.get()).unwrap_or(1)
}

fn get_all_files(paths: &[Json], extensions: &Option<Vec<String>>, ignore: &Ignore, colors: &Colors) -> Vec<String> {
    let mut all: Vec<String> = Vec::new();
    for p in paths {
        let file = match p {
            Json::Str(s) => s.clone(),
            Json::Number(n) => format!("{}", *n as i64),
            _ => continue,
        };
        match std::fs::lstat(&file) {
            Err(_) => {
                eprintln!("Skipping path {} which does not exist. \n", file);
            }
            Ok(stat) => {
                if stat.is_dir() {
                    let mut acc = DirAcc { files: Vec::new(), remaining: 1 };
                    dir_files(&file, &mut acc, ignore, colors);
                    // The callback filters; replicate list.filter(filter)
                    let list = acc.files;
                    for f in list {
                        if passes_filter(&f, extensions) {
                            all.push(f);
                        }
                    }
                } else if !passes_filter(&file, extensions) || ignore.should_ignore(&file) {
                    // ignored
                } else {
                    all.push(file);
                }
            }
        }
    }
    all
}

struct DirAcc {
    files: Vec<String>,
    remaining: u32,
}

fn dir_files(dir: &str, acc: &mut DirAcc, ignore: &Ignore, colors: &Colors) {
    let dir_path = if dir.ends_with('/') { dir.to_string() } else { format!("{}/", dir) };
    let entries = match std::fs::read_dir(&dir_path) {
        Ok(e) => e,
        Err(_) => return, // mirror: if readdir errors, throw; but we silently skip
    };
    let mut names: Vec<String> = Vec::new();
    for entry in entries.flatten() {
        names.push(entry.file_name().to_string_lossy().to_string());
    }
    acc.remaining += names.len() as u32;
    for file in names {
        let name = format!("{}{}", dir_path, file);
        match std::fs::stat(&name) {
            Err(_) => {
                print!("Skipping path \"{}\" which does not exist.\n", name);
                let _ = std::io::stdout().flush();
                done(acc);
            }
            Ok(stat) => {
                if ignore.should_ignore(&name) {
                    done(acc);
                } else if stat.is_dir() {
                    dir_files(&name, acc, ignore, colors);
                } else {
                    acc.files.push(name);
                    done(acc);
                }
            }
        }
    }
    done(acc);
}

fn done(acc: &mut DirAcc) {
    if acc.remaining > 0 {
        acc.remaining -= 1;
    }
}

fn passes_filter(name: &str, extensions: &Option<Vec<String>>) -> bool {
    match extensions {
        None => true,
        Some(exts) => {
            let ext = Path::new(name).extension().map(|e| format!(".{}", e.to_string_lossy())).unwrap_or_default();
            exts.iter().any(|e| e == &ext)
        }
    }
}

// Bridge process handling -----------------------------------------------------

struct Bridge {
    child: std::process::Child,
    stdin: std::process::ChildStdin,
}

fn spawn_bridge(transform_file: &str, opts: &RunnerOptions) -> Bridge {
    let mut cmd = Command::new("node");
    cmd.arg(&opts.bridge_path);
    cmd.arg(transform_file);
