{"command":"create","file_text":"//! Rust CLI entry point for jscodeshift, a port of bin/jscodeshift.js.

mod args;
mod colors;
mod ignore;
mod json;
mod runner;

use args::{parse_argv, ParseOutcome};
use json::Json;
use runner::RunnerOptions;
use std::io::Read;
use std::path::PathBuf;

fn main() {
    let argv: Vec<String> = std::env::args().skip(1).collect();
    let code = real_main(&argv);
    std::process::exit(code);
}

fn real_main(argv: &[String]) -> i32 {
    let specs = args::build_specs();
    let help_text = args::build_help_text(&specs);

    // Early-detect --help / --version, mirroring the nomnom `callback` semantics:
    // these are handled during parsing and short-circuit.
    let wants_help = argv.iter().any(|a| a == "--help" || a == "-h");
    let wants_version = argv.iter().any(|a| a == "--version");

    if wants_help {
        print!("{}", help_text);
        let _ = std::io::stdout().flush();
        return 0;
    }
    if wants_version {
        print!("{}", version_text());
        let _ = std::io::stdout().flush();
        return 0;
    }

    let parsed = match parse_argv(argv, &specs, &help_text) {
        ParseOutcome::Run(p) => p,
        ParseOutcome::Exit { code, message, to_stderr } => {
            if to_stderr {
                eprint!("{}", message);
            } else {
                print!("{}", message);
                let _ = std::io::stdout().flush();
            }
            return code;
        }
    };

    let options = &parsed.options;

    if parsed.positional.is_empty() && !get_bool(options, "stdin") {
        eprint!(
            "Error: You have to provide at least one file/directory to transform.\n\n---\n\n{}",
            help_text
        );
        return 1;
    }

    // Resolve paths to hand to the runner.
    let paths: Vec<Json> = if get_bool(options, "stdin") {
        let mut buffer = String::new();
        let _ = std::io::stdin().read_to_string(&mut buffer);
        buffer.split('\n').map(Json::Str).collect()
    } else {
        parsed.positional.clone()
    };

    // Resolve the transform path (relative to CWD, like path.resolve in the original).
    let transform_raw = get_str(options, "transform").unwrap_or_else(|| "./transform.js".into());
    let transform_file = if transform_raw.starts_with("http://") || transform_raw.starts_with("https://") {
        transform_raw.clone()
    } else {
        resolve_path(&transform_raw)
    };

    // Locate the package root via the executable's location so we can find the
    // bridge module and node_modules.
    let bridge_path = locate_bridge();

    // Build the options JSON handed to the bridge (and through it, the transform).
    let options_json = build_options_json(options);

    let runner_opts = RunnerOptions {
        silent: get_bool(options, "silent"),
        dry: get_bool(options, "dry"),
        verbose: get_i64(options, "verbose"),
        run_in_band: get_bool(options, "runInBand"),
        fail_on_error: get_bool(options, "failOnError"),
        cpus: get_f64(options, "cpus"),
        extensions: get_str(options, "extensions"),
        ignore_pattern: get_str_list(options, "ignorePattern"),
        ignore_config: get_str_list(options, "ignoreConfig"),
        gitignore: get_bool(options, "gitignore"),
        parser: get_str(options, "parser").unwrap_or_else(|| "babel".into()),
        parser_config: options.get("parserConfig").cloned(),
        babel: get_bool(options, "babel"),
        print: get_bool(options, "print"),
        options_json,
        bridge_path,
        cwd: std::env::current_dir()
            .map(|p| p.to_string_lossy().to_string())
            .unwrap_or_else(|_| ".".into()),
    };

    runner::run(&transform_file, &paths, &runner_opts)
}

fn get_bool(o: &std::collections::HashMap<String, Json>, k: &str) -> bool {
    o.get(k).and_then(|v| v.as_bool()).unwrap_or(false)
}
fn get_i64(o: &std::collections::HashMap<String, Json>, k: &str) -> i64 {
    o.get(k).and_then(|v| v.as_f64()).map(|n| n as i64).unwrap_or(0)
}
fn get_f64(o: &std::collections::HashMap<String, Json>, k: &str) -> Option<f64> {
    o.get(k).and_then(|v| v.as_f64())
}
fn get_str(o: &std::collections::HashMap<String, Json>, k: &str) -> Option<String> {
    o.get(k).and_then(|v| v.as_str().map(|s| s.to_string()))
}
fn get_str_list(o: &std::collections::HashMap<String, Json>, k: &str) -> Option<Vec<String>> {
    o.get(k).and_then(|v| {
        if let Json::Array(a) = v {
            Some(a.iter().filter_map(|x| x.as_str().map(|s| s.to_string())).collect())
        } else {
            None
        }
    })
}

/// Reorder the parsed options into the bridge/transform-facing JSON object.
/// The original passes the whole options object through; we serialize every
/// known option in a stable order plus any custom (unknown) options.
fn build_options_json(options: &std::collections::HashMap<String, Json>) -> Json {
    use json::ObjBuilder;
    let mut b = ObjBuilder::new();
    // Include the options the bridge/transform reads. Unknown custom options are
    // also forwarded so transforms can use them (e.g. --foo bar --num 5).
    let known = [
        "transform", "cpus", "verbose", "dry", "print", "babel", "extensions",
        "ignorePattern", "ignoreConfig", "gitignore", "runInBand", "silent",
        "parser", "parserConfig", "failOnError", "stdin",
    ];
    for k in known.iter() {
        if let Some(v) = options.get(*k) {
            b.push(k, v.clone());
        }
    }
    // Custom (unknown) options.
    for (k, v) in options.iter() {
        if !known.contains(&k.as_str()) {
            b.push(k, v.clone());
        }
    }
    b.build()
}

fn resolve_path(p: &str) -> String {
    let pb = PathBuf::from(p);
    if pb.is_absolute() {
        pb.to_string_lossy().to_string()
    } else {
        std::env::current_dir().unwrap_or_default().join(pb).to_string_lossy().to_string()
    }
}

/// Locate the bridge module relative to the executable. The Rust binary lives
/// in <pkg>/bin/jscodeshift and the bridge in <pkg>/bridge/transform-host.js.
fn locate_bridge() -> String {
    if let Ok(exe) = std::env::current_exe() {
        // exe = <pkg>/bin/jscodeshift -> pkg root = exe's parent's parent
        if let Some(bin) = exe.parent() {
            if let Some(pkg) = bin.parent() {
                let bridge = pkg.join("bridge").join("transform-host.js");
                if bridge.exists() {
                    return bridge.to_string_lossy().to_string();
                }
            }
        }
    }
    // Fallback: relative to CWD.
    "bridge/transform-host.js".to_string()
}

/// Replicate the `--version` output of the original CLI.
fn version_text() -> String {
    let pkg_version = "17.4.0";
    let root = std::env::current_exe()
        .ok()
        .and_then(|exe| exe.parent().and_then(|b| b.parent()).map(|p| p.to_path_buf()))
        .unwrap_or_else(|| PathBuf::from("."));
    let babel = read_pkg_version(&root, "@babel/core").unwrap_or_default();
    let babylon = read_pkg_version(&root, "@babel/parser").unwrap_or_default();
    let flow = read_pkg_version(&root, "flow-parser").unwrap_or_default();
    let recast = read_pkg_version(&root, "recast").unwrap_or_default();
    format!(
        "jscodeshift: {}\n - babel: {}\n - babylon: {}\n - flow: {}\n - recast: {}\n",
        pkg_version, babel, babylon, flow, recast
    )
}

fn read_pkg_version(root: &PathBuf, name: &str) -> Option<String> {
    let candidates: Vec<PathBuf> = if name.starts_with("@babel") {
        vec![root.join("node_modules").join(name).join("package.json")]
    } else {
        vec![
            root.join("node_modules").join(name).join("package.json"),
            // requirePackage walks up from the resolved entry; recast resolves under
            // its own dir, so also try nested copies.
            root.join("node_modules").join(name).join("package.json"),
        ]
    };
    for c in candidates {
        if let Ok(content) = std::fs::read_to_string(&c) {
            if let Ok(Json::Object(entries)) = json::parse(&content) {
                for (k, v) in entries {
                    if k == "version" {
                        if let Json::Str(s) = v {
                            return Some(s);
                        }
                    }
                }
            }
        }
    }
    None
