{"command":"create","file_text":"/*
 * transform-host.js â minimal compatibility bridge that loads and executes
 * jscodeshift transforms in Node.js. It is the JavaScript surface retained by
 * the Rust port of jscodeshift and is driven over stdin/stdout/stderr by the
 * Rust control layer (see src-rs/runner.rs).
 *
 * Protocol:
 *   argv: <transformFile> <"babel" | "no-babel">
 *   stdin : one JSON object per line: {"files":[...paths], "options":{...}}
 *           An empty files array (or EOF on stdin) signals the worker to exit.
 *   stdout: pass-through for transform `console.log` / `--print` output.
 *   stderr: one JSON object per line, a control message:
 *             {"action":"status","status":"ok|error|nochange|skip","msg":"<path> ..."}
 *             {"action":"update","name":"<stat>","quantity":<n>}
 *             {"action":"report","file":"<path>","msg":"<text>"}
 *             {"action":"free"}
 *           Lines that are not control JSON (e.g. transform stack traces) are
 *           emitted verbatim and passed through to the terminal by the Rust side.
 *
 * This bridges the original src/Worker.js semantics onto a line-based IPC so the
 * Rust process can own process pooling and file discovery.
 */

"use strict";

const fs = require("fs");
const path = require("path");
const os = require("os");
const readline = require("readline");

// Send a control message to the Rust runner over stderr.
function send(obj) {
  process.stderr.write(JSON.stringify(obj) + "\n");
}

function main() {
  const transformFile = process.argv[2];
  const useBabel = process.argv[3] !== "no-babel";

  let transform = null;
  let transformInitialized = false;

  // Lazily load + initialize the transform module. Mirrors Worker.js: the
  // transform is required once per worker process, and its `initialize` hook
  // (if present) is awaited before any file is processed.
  function ensureTransform(options) {
    if (transformInitialized) {
      return Promise.resolve(transform);
    }
    transformInitialized = true;
    let mod;
    if (useBabel) {
      // Use the babel hooks registered by the main package so transforms are
      // transpiled on require, matching the default `--babel` behavior.
      try {
        require("@babel/register")({
          babelrc: false,
          configFile: false,
          plugins: [require.resolve("@babel/plugin-transform-modules-commonjs")],
          ignore: [],
          cache: false,
        });
      } catch (e) {
        // fall back to plain require if @babel/register is unavailable
      }
    }
    try {
      mod = require(path.resolve(transformFile));
    } catch (e) {
      send({ action: "status", status: "error", msg: "Transform load error: " + (e && e.message || String(e)) });
      // We keep the worker alive so the parent can drain; subsequent files will
      // also fail to transform.
      transform = null;
      return Promise.resolve(null);
    }
    if (mod && typeof mod.default === "function" && typeof mod !== "function") {
      mod = mod.default;
    }
    transform = mod;
    if (mod && typeof mod.initialize === "function") {
      return Promise.resolve(mod.initialize(options || {})).then(() => mod);
    }
    return Promise.resolve(mod);
  }

  const rl = readline.createInterface({ input: process.stdin, terminal: false });

  let busy = false;
  let pending = null;

  function processLine(line) {
    let payload;
    try {
      payload = JSON.parse(line);
    } catch (e) {
      return;
    }
    const files = payload.files || [];
    const options = payload.options || {};
    runChunk(files, options, () => {
      send({ action: "free" });
      if (files.length === 0) {
        // Empty chunk: parent is signaling completion; close stdin handled by EOF.
      }
    });
  }

  function runChunk(files, options, done) {
    if (files.length === 0) {
      done();
      return;
    }
    ensureTransform(options).then((mod) => {
      return files.reduce((promise, file) => {
        return promise.then(() => processFile(mod, file, options));
      }, Promise.resolve());
    }).then(() => {
      done();
    }).catch((e) => {
      // Should not normally happen; per-file errors are handled in processFile.
      done();
    });
  }

  function processFile(mod, file, options) {
    return new Promise((resolve) => {
      if (!mod || typeof mod !== "function") {
        send({ action: "status", status: "error", msg: file + " transform not a function" });
        return resolve();
      }
      let source;
      try {
        source = fs.readFileSync(file, "utf8");
      } catch (e) {
        send({ action: "status", status: "error", msg: file + " " + (e && e.message || String(e)) });
        return resolve();
      }

      // Build the jscodeshift facade the same way src/core.js does, so the
      // transform receives the standard `(fileInfo, api) => ...` contract.
      const j = buildApi(options);
      let result;
      try {
        result = mod({ path: file, source }, { j, jscodeshift: j, stats: makeStats(file, options) }, options);
      } catch (e) {
        // Replicate Worker.js: a thrown error during transform becomes ERR.
        let msg = file;
        if (e && e.message) {
          msg += " " + e.message;
        } else if (typeof e === "string") {
          // The original Worker.js does `err.message` -> crashes when undefined.
          // Preserve that observable behavior by emitting a status with the
          // non-string coercion result. Here we just forward the string.
          msg += " " + e;
        }
        send({ action: "status", status: "error", msg: msg });
        return resolve();
      }

      Promise.resolve(result).then((out) => {
        if (out === undefined || out === null) {
          send({ action: "status", status: "nochange", msg: file });
          return resolve();
        }
        const output = typeof out === "string" ? out : "";
        if (output === source) {
          send({ action: "status", status: "nochange", msg: file });
          return resolve();
        }
        if (options.dry) {
          send({ action: "status", status: "ok", msg: file });
          return resolve();
        }
        if (options.print) {
          process.stdout.write(output);
          send({ action: "status", status: "ok", msg: file });
          return resolve();
        }
        try {
          fs.writeFileSync(file, output);
          send({ action: "status", status: "ok", msg: file });
        } catch (e) {
          send({ action: "status", status: "error", msg: file + " " + (e && e.message || String(e)) });
        }
        resolve();
      }).catch((e) => {
        let msg = file;
        if (e && e.message) msg += " " + e.message;
        else if (typeof e === "string") msg += " " + e;
        send({ action: "status", status: "error", msg: msg });
        resolve();
      });
    });
  }

  function makeStats(file, options) {
    // The `stats` helper forwards `update`/`report` to the runner.
    return {
      update: function (name, quantity) {
        send({ action: "update", name: String(name), quantity: quantity || 1 });
      },
      report: function (msg) {
        send({ action: "report", file: file, msg: String(msg) });
      },
    };
  }

  function buildApi(options) {
    // Reuse the package's own core API so collections, builders, templates and
    // parsers behave identically to the JS implementation.
    const core = require(path.join(__dirname, "..", "src", "core"));
    return core.withParser(options.parser || "babel");
  }

  rl.on("line", processLine);
  rl.on("close", () => {
    // Parent closed stdin; allow any in-flight work then exit.
    process.exit(0);
  });
}

