{"command":"create","path":"/workspace/codebase/bridge/transform-host.js","file_text":"/*
 * transform-host.js â minimal compatibility bridge that loads and executes
 * jscodeshift transforms in Node.js. It is the JavaScript surface retained by
 * the Rust port of jscodeshift and is driven over stdin/stdout/stderr by the
 * Rust control layer (see src-rs/runner.rs).
 *
 * Protocol:
 *   argv: <transformFile> <"babel" | "no-babel">
 *   stdin : one JSON object per line: {"files":[...paths], "options":{...}}
 *           An empty files array (or EOF on stdin) signals the worker to exit.
 *   stdout: pass-through for transform `console.log` / `--print` output.
 *   stderr: one JSON object per line, a control message:
 *             {"action":"status","status":"ok|error|nochange|skip","msg":"<path> ..."}
 *             {"action":"update","name":"<stat>","quantity":<n>}
 *             {"action":"report","file":"<path>","msg":"<text>"}
 *             {"action":"free"}
 *             {"action":"done"}
 *           Lines that are not control JSON (e.g. transform stack traces) are
 *           emitted verbatim and passed through to the terminal by Rust.
 *
 * Rather than re-implement the worker logic, this bridge drives the original
 * first-party src/Worker.js in its in-process (module.parent) emitter mode,
 * whose contract mirrors child_process.fork:
 *   worker.send({files, options}) -> run a chunk
 *   'message' events             -> {action:'status'|'update'|'free'|'report'}
 *   'disconnect'                 -> worker finished (only on empty files)
 * Delegating to Worker.js keeps every observable detail identical to the JS
 * implementation: babel register setup, graceful-fs reads, write-file-atomic
 * writes, and the exact source location (src/Worker.js) where transform errors
 * surface in stack traces. This file is only line-based IPC glue translating
 * the emitter's process.send / on('message') protocol onto stdin/stderr JSON so
 * the Rust process can own worker pooling and file discovery.
 */

"use strict";

const path = require("path");
const readline = require("readline");

function send(obj) {
  process.stderr.write(JSON.stringify(obj) + "\n");
}

function main() {
  const transformFile = process.argv[2];
  const useBabel = process.argv[3] !== "no-babel";

  let shuttingDown = false;
  function shutdown() {
    if (shuttingDown) {
      return;
    }
    shuttingDown = true;
    send({ action: "done" });
    setImmediate(() => process.exit(0));
  }

  const workerPath = path.join(__dirname, "..", "src", "Worker.js");
  let worker;
  try {
    worker = require(workerPath)([transformFile, useBabel ? "babel" : "no-babel"]);
  } catch (e) {
    send({
      action: "status",
      status: "error",
      msg: "Transform load error: " + ((e && e.message) || String(e)),
    });
    shutdown();
    return;
  }

  let finished = false;
  worker.on("message", (message) => {
    // Forward every control message Worker.js emits verbatim.
    send(message);
  });
  worker.on("disconnect", () => {
    // Worker.js emits 'disconnect' only when handed an empty files array
    // (the shutdown signal). Acknowledge done and exit.
    finished = true;
    shutdown();
  });

  const rl = readline.createInterface({ input: process.stdin, terminal: false });

  function processLine(line) {
    let payload;
    try {
      payload = JSON.parse(line);
    } catch (e) {
      return;
    }
    const files = payload.files || [];
    const options = payload.options || {};
    // Hand the chunk (possibly empty == shutdown) to Worker.js. An empty
    // files array triggers finish() -> 'disconnect' -> done, matching the
    // forked worker's process.disconnect behavior.
    worker.send({ files, options });
  }

  rl.on("line", processLine);
  rl.on("close", () => {
    if (!finished) {
      shutdown();
    }
  });
}

main();"}

